"""
	inch to feet&inch, all strings
	u3 is a tuple of (feet, inch)
	"""
def u2u3(u2: Any) -> object {
    u2 = float(u2);
    f = u2 // 12;
    i = u2 % 12;
    inch_int = int((i // 1));
    inch_frac = i % 1;
    `test = round((inch_frac / 0.25));
    if (`test == 0) {
        i = str(inch_int);
    } elif (`test == 4) {
        i = str((inch_int + 1));
    } elif (`test == 2) {
        i = str(inch_int) + " 1/2";
    } else {
        i = str(inch_int) + " " + str(`test) + "/4";
    }
    return (str(int(f)), i);
}
